import torch

_MAX_GRAPHS = 4
_MAX_KEYS = 64

_SCALARS = {}
_STATE = {"graphs": {}, "seen": {}, "disabled": False}


def _scalar(device, value):
    """Cached 0-dim FP32 constant on `device` (no per-call host->device copy)."""
    key = (str(device), value)
    tensor = _SCALARS.get(key)
    if tensor is None:
        tensor = torch.tensor(value, dtype=torch.float32, device=device)
        _SCALARS[key] = tensor
    return tensor


def _affine_out(x, y, out, device):
    """out = relu(1.25 * x + 0.75 * y - 0.125) using exactly three kernels."""
    torch.addcmul(_scalar(device, -0.125), x, _scalar(device, 1.25), out=out)
    out.addcmul_(y, _scalar(device, 0.75))
    out.clamp_min_(0.0)
    return out


def _run_eager(x, y):
    return _affine_out(x, y, torch.empty_like(x), x.device)


def _key(x, y):
    return (
        x.data_ptr(),
        y.data_ptr(),
        x.device.index,
        tuple(x.shape),
        tuple(y.shape),
        tuple(x.stride()),
        tuple(y.stride()),
    )


def _try_capture(x, y, key):
    """Capture the three-kernel sequence once; return (graph, out) or None."""
    try:
        device = x.device
        out = torch.empty_like(x)

        # Warm the exact op sequence outside capture so no lazy init (kernel
        # load, workspace query) happens while the stream is being captured.
        warm = torch.cuda.Stream(device=device)
        warm.wait_stream(torch.cuda.current_stream(device))
        with torch.cuda.stream(warm):
            _affine_out(x, y, out, device)
            _affine_out(x, y, out, device)
        torch.cuda.current_stream(device).wait_stream(warm)

        graph = torch.cuda.CUDAGraph()
        with torch.cuda.graph(graph):
            _affine_out(x, y, out, device)

        # Capture records the kernels without executing them, so produce this
        # call's result with a replay.
        graph.replay()
        _STATE["graphs"][key] = (graph, out)
        return graph, out
    except Exception:
        return None


