    x = inputs["x"]
    y = inputs["y"]

    if not (x.is_cuda and y.is_cuda and x.dtype == torch.float32 and y.dtype == torch.float32):
        return _run_eager(x, y)

    key = _key(x, y)
    entry = _STATE["graphs"].get(key)
    if entry is not None:
        graph, out = entry
        graph.replay()
        return out

