# Scalar operands are 0-dim device tensors created once per device: rebuilding them
# per call would add a host->device copy to every invocation.
_SCALARS = {}

def _scalars(device):
    key = str(device)
    cached = _SCALARS.get(key)
    if cached is None:
        cached = (
            torch.tensor(-0.125, dtype=torch.float32, device=device),
            torch.tensor(0.75, dtype=torch.float32, device=device),
        )
        _SCALARS[key] = cached
    return cached

def run(inputs):
    # Fused affine + relu path: 3 small kernels, one allocation, no redundant copy.
    #   out = (1.25 * x - 0.125) + 0.75 * y ;  return relu(out)
    x = inputs['x']
    y = inputs['y']
    bias, wy = _scalars(x.device)
    out = torch.add(bias, x, alpha=1.25)   # 1.25 * x - 0.125, single fresh buffer
    out.addcmul_(y, wy)                    # += 0.75 * y, in place
    return torch.relu_(out)                # in place, no extra allocation
